template<typename... Args>
void function_caller(Args... args) {
    // Size of parameter pack (value)
    constexpr size_t count = sizeof...(Args);
    // Unpacking into initializer list (C++11 trick)
    int expansion[] = { ( (std::cout << args << ' '), 0)... };
}

