// C++17 Fold Expression Example
template<typename... Nums>
auto sum_fold(Nums... nums) {
    // Right fold (starts with 0)
    return (0 + ... + nums);
}

// Using fold for side effects
template<typename... Fns>
void execute_all(Fns... f) {
    // Comma fold expression (guaranteed order C++17)
    (f(), ...);
}

