// Variadic Class Template Definition
template<typename... Types>
class TypeList {};

// Specialization (Recursive structure)
template<typename T, typename... Rest>
class TypeList<T, Rest...> : public TypeList<Rest...> {
public:
    using HeadType = T;
    // Parameter pack size
    static constexpr size_t N = sizeof...(Rest) + 1;
};

